import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
class ProductionStockPage extends StatelessWidget {
  const ProductionStockPage({super.key});
  CollectionReference<Map<String,dynamic>> c(String n)=>FirebaseFirestore.instance.collection('sharedData').doc('dailyHisab').collection(n);
  double n(dynamic v)=>v is num?v.toDouble():double.tryParse('$v')??0;
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Production Unit Stock')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:c('products').snapshots(),builder:(context,p){if(p.hasError)return Center(child:Text('Unable to load products: ${p.error}'));if(!p.hasData)return const Center(child:CircularProgressIndicator());return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:c('production').snapshots(),builder:(context,pr){return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:c('stockTransfers').snapshots(),builder:(context,tr){if(pr.hasError||tr.hasError)return Center(child:Text('Unable to load stock. ${pr.error??tr.error}'));if(!pr.hasData||!tr.hasData)return const Center(child:CircularProgressIndicator());final products=p.data!.docs.where((d)=>d.data()['active']!=false),made=pr.data!.docs.map((d)=>d.data()).toList(),moved=tr.data!.docs.map((d)=>d.data()).toList();return ListView(padding:const EdgeInsets.all(16),children:[const Card(child:ListTile(title:Text('Production Unit',style:TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('Production less quantities transferred to retail shops.'))),...products.map((x){final id=x.id,a=made.where((z)=>z['productId']?.toString()==id).fold<double>(0,(s,z)=>s+n(z['quantity'])),b=moved.where((z)=>z['productId']?.toString()==id).fold<double>(0,(s,z)=>s+n(z['quantity']));return ListTile(title:Text(x.data()['name']?.toString()??id),subtitle:Text('Produced: ${a.toStringAsFixed(2)}  •  Transferred: ${b.toStringAsFixed(2)}'),trailing:Text('${(a-b).toStringAsFixed(2)} Box',style:const TextStyle(fontWeight:FontWeight.bold)));})]);});});}));}
}
